-- MySQL backup - import in phpMyAdmin (XAMPP)
CREATE DATABASE IF NOT EXISTS phonebook_backup CHARACTER SET utf8mb4; USE phonebook_backup;
CREATE TABLE IF NOT EXISTS settings (id INT AUTO_INCREMENT PRIMARY KEY, `key` VARCHAR(120) UNIQUE NOT NULL, value TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS contacts (id INT AUTO_INCREMENT PRIMARY KEY, first_name VARCHAR(120) NOT NULL, last_name VARCHAR(120) DEFAULT '', nickname VARCHAR(120) DEFAULT '', dob DATE NULL, email VARCHAR(255) DEFAULT '', phone VARCHAR(60) DEFAULT '', phone2 VARCHAR(60) DEFAULT '', address TEXT, city VARCHAR(120) DEFAULT '', state VARCHAR(120) DEFAULT '', zip VARCHAR(30) DEFAULT '', country VARCHAR(120) DEFAULT 'USA', relationship VARCHAR(80) DEFAULT 'Friend', gender VARCHAR(40) DEFAULT '', pronouns VARCHAR(60) DEFAULT '', company VARCHAR(180) DEFAULT '', job_title VARCHAR(180) DEFAULT '', tags TEXT, notes TEXT, is_favorite TINYINT(1) DEFAULT 0, avatar_color VARCHAR(30) DEFAULT '#6366f1', how_we_met TEXT, anniversary DATE NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS accounts (id INT AUTO_INCREMENT PRIMARY KEY, contact_id INT NOT NULL, label VARCHAR(180) NOT NULL, type VARCHAR(60) DEFAULT 'Other', username VARCHAR(255) DEFAULT '', email VARCHAR(255) DEFAULT '', password TEXT, website VARCHAR(500) DEFAULT '', bank_name VARCHAR(180) DEFAULT '', routing_number VARCHAR(60) DEFAULT '', account_number VARCHAR(80) DEFAULT '', account_type VARCHAR(60) DEFAULT '', notes TEXT, is_primary TINYINT(1) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(contact_id) REFERENCES contacts(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS journal_entries (id INT AUTO_INCREMENT PRIMARY KEY, contact_id INT NOT NULL, entry_date DATE NOT NULL, title VARCHAR(255) NOT NULL, entry_type VARCHAR(60) DEFAULT 'Note', is_intimate TINYINT(1) DEFAULT 0, mood VARCHAR(60) DEFAULT '', location VARCHAR(255) DEFAULT '', notes TEXT, rating INT DEFAULT 0, intimacy_type VARCHAR(120) DEFAULT '', protection_used VARCHAR(120) DEFAULT '', contraception_notes TEXT, consent_confirmed TINYINT(1) DEFAULT 0, duration_minutes INT DEFAULT 0, satisfaction INT DEFAULT 0, partner_satisfaction INT DEFAULT 0, emotional_closeness INT DEFAULT 0, communication_rating INT DEFAULT 0, activities TEXT, position_notes TEXT, orgasm VARCHAR(60) DEFAULT '', aftercare TEXT, mood_before VARCHAR(80) DEFAULT '', mood_after VARCHAR(80) DEFAULT '', health_concerns TEXT, sti_tested_recent TINYINT(1) DEFAULT 0, would_repeat VARCHAR(40) DEFAULT '', what_went_well TEXT, what_to_improve TEXT, is_private TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(contact_id) REFERENCES contacts(id) ON DELETE CASCADE) ENGINE=InnoDB;
